    private void trackList(LinearLayout list,JSONArray tracks,boolean removable){if(tracks.length()==0)list.addView(ui.text("Nenhuma faixa ainda. Marque ♥ ou adicione uma música à playlist.",15,Ui.MUTED));for(int n=0;n<tracks.length();n++){JSONObject t=tracks.optJSONObject(n);if(t==null)continue;int index=n;LinearLayout row=ui.row();ui.pad(row,4,10);LinearLayout labels=ui.column();labels.addView(ui.title(t.optString("title"),15));labels.addView(ui.text(t.optString("artist")+" • "+t.optString("provider"),12,Ui.MUTED));ui.weight(row,labels);row.addView(ui.icon("play","Reproduzir "+t.optString("title"),()->{JSONArray queue=new JSONArray();for(int i=index;i<tracks.length();i++)queue.put(tracks.opt(i));play.accept(queue);dialog.dismiss();}));row.addView(ui.icon("more","Opções da música",()->new AlertDialog.Builder(activity).setItems(removable?new String[]{"Favoritar / desfavoritar","Adicionar a playlist","Remover desta playlist"}:new String[]{"Favoritar / desfavoritar","Adicionar a playlist"},(d,w)->{if(w==0)favorite(t);else if(w==1)addTo(t);else{store.remove(playlist,index);render();}}).show()));list.addView(row);}}
