        int[] spans={7,30,90,180};String[] dims={"artists","tracks","genres","days"};LinearLayout filters=ui.row();ui.weight(filters,selector(new String[]{"7 dias","30 dias","90 dias","180 dias"},days==7?0:days==30?1:days==90?2:3,n->{days=spans[n];render();}));ui.weight(filters,selector(new String[]{"Artistas","Músicas","Estilos","Por dia"},Arrays.asList(dims).indexOf(dimension),n->{dimension=dims[n];render();}));content.addView(filters);
